    try {
      await db.execute(sql`ALTER TABLE quizzes ADD COLUMN IF NOT EXISTS test_date TIMESTAMP`);
      console.log("Added test_date column to quizzes table");
    } catch (error) {
      console.log("test_date column already exists or error:", error);
