                    </Badge>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Mock Test Creation Dialog */}
      <Dialog open={showMockTestDialog} onOpenChange={setShowMockTestDialog}>
        <DialogContent className="sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle>Create Mock Test</DialogTitle>
            <DialogDescription>
              Configure your mock test with {questions.length + fileQuestions.filter(q => selectAllFile || q.isSelected).length} selected questions.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="title" className="text-right">
                Title
              </Label>
              <Input
                id="title"
                value={mockTestData.title}
                onChange={(e) => setMockTestData(prev => ({ ...prev, title: e.target.value }))}
                className="col-span-3"
                placeholder="Enter mock test title"
              />
            </div>

            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="description" className="text-right">
                Description
              </Label>
              <Textarea
                id="description"
                value={mockTestData.description}
                onChange={(e) => setMockTestData(prev => ({ ...prev, description: e.target.value }))}
                className="col-span-3"
                placeholder="Enter test description"
                rows={3}
              />
            </div>

            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="duration" className="text-right">
                Duration (minutes)
              </Label>
              <Input
                id="duration"
                type="number"
                value={mockTestData.duration}
                onChange={(e) => setMockTestData(prev => ({ ...prev, duration: parseInt(e.target.value) || 120 }))}
                className="col-span-3"
                min="30"
                max="300"
              />
            </div>

            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="scheduledDate" className="text-right">
                Scheduled Date
              </Label>
              <Input
                id="scheduledDate"
                type="date"
                value={mockTestData.scheduledDate}
                onChange={(e) => setMockTestData(prev => ({ ...prev, scheduledDate: e.target.value }))}
                className="col-span-3"
              />
            </div>

            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="difficulty" className="text-right">
                Difficulty
              </Label>
              <Select
                value={mockTestData.difficulty}
                onValueChange={(value) => setMockTestData(prev => ({ ...prev, difficulty: value }))}
              >
                <SelectTrigger className="col-span-3">
                  <SelectValue placeholder="Select difficulty" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="easy">Easy</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="hard">Hard</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowMockTestDialog(false)}>
              Cancel
            </Button>
            <Button
              onClick={async () => {
                const allQuestions = [
                  ...questions,
                  ...fileQuestions.filter(q => selectAllFile || q.isSelected)
                ];

                if (allQuestions.length === 0) {
                  toast({
                    title: "No Questions Selected",
                    description: "Please add or select questions before creating a mock test.",
                    variant: "destructive"
                  });
                  return;
                }

                if (!mockTestData.title.trim()) {
                  toast({
                    title: "Title Required",
                    description: "Please enter a title for the mock test.",
                    variant: "destructive"
                  });
                  return;
                }

                try {
                  // First save questions to get their IDs
                  const response = await apiRequest("POST", "/api/admin/questions/manual", {
                    questions: allQuestions,
                    subjectId: selectedSubject || "1",
                    topicId: selectedTopic || "1"
                  });

                  const savedQuestionsData = await response.json();
                  const questionIds = savedQuestionsData.questions?.map((q: any) => q.id) || [];

                  if (questionIds.length === 0) {
                    throw new Error("Failed to save questions");
                  }

                  // Then create mock test with question IDs
                  const mockTestResponse = await apiRequest("POST", "/api/admin/create-mock-test", {
                    title: mockTestData.title,
                    description: mockTestData.description,
                    duration: mockTestData.duration,
                    testDate: mockTestData.scheduledDate,
                    selectedQuestionIds: questionIds
                  });

                  const mockTestResult = await mockTestResponse.json();

                  if (mockTestResult.success) {
                    toast({
                      title: "Mock Test Created Successfully",
                      description: `Mock test "${mockTestData.title}" has been created with ${questionIds.length} questions.`
                    });
                    setShowMockTestDialog(false);
                    setQuestions([]);
                    setFileQuestions([]);
                    setMockTestData({
                      title: "",
                      description: "",
                      duration: 120,
                      scheduledDate: new Date().toISOString().split('T')[0],
                      difficulty: "medium"
                    });
                  } else {
                    throw new Error(mockTestResult.error || "Failed to create mock test");
                  }
                } catch (error) {
                  console.error("Mock test creation error:", error);
                  toast({
                    title: "Error",
                    description: error instanceof Error ? error.message : "Failed to create mock test",
                    variant: "destructive"
                  });
                }
              }}
              disabled={createMockTestMutation.isPending}
              className="bg-gradient-to-r from-blue-500 to-blue-600"
            >
              {createMockTestMutation.isPending ? (
                <>
                  <div className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-b-transparent"></div>
                  Creating...
                </>
              ) : (
                <>
                  <Calendar className="mr-2 h-4 w-4" />
                  Create Mock Test
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

